float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_g0(uv);if(tex==2) return amzSample_g1(uv);if(tex==3) return amzSample_g2(uv);if(tex==4) return amzSample_g3(uv);if(tex==5) return amzSample_g4(uv);if(tex==6) return amzSample_g5(uv);if(tex==7) return amzSample_g6(uv);return float4(0.0); }
