uniform float amzp_bevelStyle;
layout(color) uniform half4 amzp_tintCol;
layout(color) uniform half4 amzp_colA;
layout(color) uniform half4 amzp_colB;
layout(color) uniform half4 amzp_colC;
layout(color) uniform half4 amzp_hiCol;
layout(color) uniform half4 amzp_shCol;
layout(color) uniform half4 amzp_borderCol;
uniform float amzp_alpha;
uniform float amzp_blur;
uniform float amzp_glassOp;
uniform float amzp_origMix;
uniform float amzp_sat;
uniform float amzp_bright;
uniform float amzp_frost;
uniform float amzp_refr;
uniform float amzp_disp;
uniform float amzp_gradAngle;
uniform float amzp_blobCount;
uniform float amzp_blobSize;
uniform float amzp_blobSoft;
uniform float amzp_seed;
uniform float amzp_bevelOn;
uniform float amzp_bevelSize;
uniform float amzp_bevelDepth;
uniform float amzp_lightAngle;
uniform float amzp_lightHeight;
uniform float amzp_hiStr;
uniform float amzp_shStr;
uniform float amzp_backStr;
uniform float amzp_specStr;
uniform float amzp_shin;
uniform float amzp_innerGlow;
uniform float amzp_borderOn;
uniform float amzp_borderW;
uniform float amzp_borderLit;
