uniform float amzp_innerStr;
uniform float amzp_innerDist;
uniform float amzp_innerBlur;
uniform float amzp_dropOn;
layout(color) uniform half4 amzp_dropCol;
uniform float amzp_dropAngle;
uniform float amzp_dropDist;
uniform float amzp_dropBlur;
uniform float amzp_dropKnock;
uniform float amzp_overdrawOn;
