    float4 encL(float4 v) { return sqrt(max(v, float4(0.0))); }
    float4 decL(float4 e) { return e * e; }
    float4 rd(int t, float2 uv) {
        float2 ins = step(float2(0.0), uv) * step(uv, float2(1.0));
        return decL(amzTexture(t, uv)) * (ins.x * ins.y);
    }
    float4 shrink(int tx, float2 uv, float2 t) {
        float4 sum = rd(tx, uv) * 0.125;
        sum += (rd(tx, uv + float2(-2.0, 2.0) * t) + rd(tx, uv + float2(2.0, 2.0) * t)
              + rd(tx, uv + float2(-2.0, -2.0) * t) + rd(tx, uv + float2(2.0, -2.0) * t)) * 0.03125;
        sum += (rd(tx, uv + float2(0.0, 2.0) * t) + rd(tx, uv + float2(-2.0, 0.0) * t)
              + rd(tx, uv + float2(2.0, 0.0) * t) + rd(tx, uv + float2(0.0, -2.0) * t)) * 0.0625;
        sum += (rd(tx, uv + float2(-1.0, 1.0) * t) + rd(tx, uv + float2(1.0, 1.0) * t)
