        s += rd(tx, uv + t) + rd(tx, uv - t) + rd(tx, uv + float2(t.x, -t.y)) + rd(tx, uv + float2(-t.x, t.y));
        return s * 0.0625;
    }
    float4 lv(int k, float2 uv) {
        if (k <= 0) return soft(1, uv, 1.0 / getTexSize((screen.zw/2.0)));
        if (k == 1) return soft(2, uv, 1.0 / getTexSize((screen.zw/4.0)));
        if (k == 2) return soft(3, uv, 1.0 / getTexSize((screen.zw/8.0)));
        if (k == 3) return soft(4, uv, 1.0 / getTexSize((screen.zw/16.0)));
        if (k == 4) return soft(5, uv, 1.0 / getTexSize((screen.zw/32.0)));
        if (k == 5) return soft(6, uv, 1.0 / getTexSize((screen.zw/64.0)));
        return soft(7, uv, 1.0 / getTexSize((screen.zw/128.0)));
    }
    float tapA(int k, float2 uv) {
        if (k < 0) return amzTexture(0, uv).a;
        if (k == 0) return rd(1, uv).a;
        if (k == 1) return rd(2, uv).a;
        if (k == 2) return rd(3, uv).a;
        if (k == 3) return rd(4, uv).a;
        if (k == 4) return rd(5, uv).a;
        if (k == 5) return rd(6, uv).a;
        return rd(7, uv).a;
    }
    float4 blurAt(float2 uvS, float B, float4 sharp) {
        float l = log(max(B, 1e-3) / 0.8) * 1.442695 - 1.0;
        if (l <= 0.0) return mix(sharp, lv(0, uvS), clamp(B / 1.6, 0.0, 1.0));
        if (l >= 6.0) return lv(6, uvS);
        int k = int(floor(l));
        return mix(lv(k, uvS), lv(k + 1, uvS), l - floor(l));
    }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float hh(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.17) * 43758.5453); }
    float4 ov(float4 top, float4 bot) { return top + bot * (1.0 - top.a); }
    void edgeField(float2 uvL, float R, out float h, out float2 g) {
        float2 W = layer;
        float n = amzp_quality < 1.5 ? 40.0 : (amzp_quality < 2.5 ? 64.0 : (amzp_quality < 3.5 ? 96.0 : (amzp_quality < 4.5 ? 136.0 : 192.0)));
        float sg = R * 0.45;
        float lt = log(max(R, 1.0) / 8.0) * 1.442695 - 1.0;
        int kT = lt < 0.0 ? -1 : int(min(floor(lt), 6.0));
        h = 0.0; g = float2(0.0);
        float ws = 0.0;
        for (int i = 0; i < 192; i++) {
            float fi = float(i);
            if (fi >= n) break;
            float rho = R * sqrt((fi + 0.5) / n);
            float2 d = rho * float2(cos(fi * 2.3999632), sin(fi * 2.3999632));
            float w0 = exp(-rho * rho / (2.0 * sg * sg));
            float al = tapA(kT, l2s(uvL + d / W));
            h += w0 * al;
            g += w0 * al * d;
            ws += w0;
        }
        h /= ws;
        g /= ws * sg * sg;
    }
    float3 gradCol(float2 uvL) {
        float2 W = layer;
        float2 q = (uvL - 0.5) * W;
        float an = radians(amzp_gradAngle);
        float2 dv = float2(cos(an), sin(an));
        float hl = max(0.5 * (abs(W.x * dv.x) + abs(W.y * dv.y)), 1.0);
        float t = clamp(dot(q, dv) / (2.0 * hl) + 0.5, 0.0, 1.0);
        return t < 0.5 ? mix(amzp_colA.rgb, amzp_colB.rgb, t * 2.0) : mix(amzp_colB.rgb, amzp_colC.rgb, t * 2.0 - 1.0);
    }
    float3 auroraCol(float2 uvL) {
