            float2 c = float2(hh(float2(fi, 1.0)), hh(float2(fi, 2.0))) * W;
            float rr = amzp_blobSize * msz * (0.6 + 0.8 * hh(float2(fi, 3.0)));
            float2 dq = (q - c) / rr;
            float w = exp(-dot(dq, dq) * kk * 0.5);
            float m3 = mod(fi, 3.0);
            float3 cc = m3 < 0.5 ? amzp_colA.rgb : (m3 < 1.5 ? amzp_colB.rgb : amzp_colC.rgb);
            cs += cc * w;
            wsum += w;
        }
        float3 bg = mix(amzp_colA.rgb, amzp_colB.rgb, 0.5) * 0.25;
        float3 bl = cs / max(wsum, 1e-3);
        return mix(bg, bl, 1.0 - exp(-wsum * 1.6));
    }
    void amzRender() {
        float2 uvS = amzScreenNorm();
        if (amzPass == 0) {
            float2 h = 0.5 / getTexSize((screen.zw/1.0));
            float4 c = (amzTexture(0, uvS + float2(-h.x, -h.y)) + amzTexture(0, uvS + float2(h.x, -h.y))
                    + amzTexture(0, uvS + float2(-h.x, h.y)) + amzTexture(0, uvS + float2(h.x, h.y))) * 0.25;
            amzOutput = encL(c);
            return;
        }
        if (amzPass == 1) { amzOutput = shrink(1, uvS, 1.0 / getTexSize((screen.zw/2.0))); return; }
        if (amzPass == 2) { amzOutput = shrink(2, uvS, 1.0 / getTexSize((screen.zw/4.0))); return; }
        if (amzPass == 3) { amzOutput = shrink(3, uvS, 1.0 / getTexSize((screen.zw/8.0))); return; }
        if (amzPass == 4) { amzOutput = shrink(4, uvS, 1.0 / getTexSize((screen.zw/16.0))); return; }
        if (amzPass == 5) { amzOutput = shrink(5, uvS, 1.0 / getTexSize((screen.zw/32.0))); return; }
        if (amzPass == 6) { amzOutput = shrink(6, uvS, 1.0 / getTexSize((screen.zw/64.0))); return; }
        float2 W = layer;
        float2 uvL = amzLayerNorm();
        float4 src = amzTexture(0, uvS);
