            float e = 1.0 - smoothstep(0.5, 1.0, h);
            float2 off = abs(amzp_refr) > 0.01 ? gd * amzp_refr * e / W : float2(0.0);
            float2 uvLr = uvL + off;
            float3 col;
            if (int(amzp_fillMode) == 0) {
                float2 uvSr = l2s(uvLr);
                float4 b = blurAt(uvSr, amzp_blur, amzTexture(0, uvSr));
                col = b.rgb / max(b.a, 0.02);
                if (amzp_disp > 0.01) {
                    float2 dd = gd * amzp_disp * e / W;
                    float2 uR = l2s(uvLr + dd), uB = l2s(uvLr - dd);
