            col = clamp(col, 0.0, 1.0);
            float bodyA = (int(amzp_fillMode) == 3 ? a * amzp_tintCol.a : a) * amzp_glassOp;
            res = float4(col * bodyA, bodyA);
            if ((amzp_innerOn>0.5)) {
                float2 so = -L2 * amzp_innerDist;
                float2 uS = l2s(uvL + so / W);
                float sa = blurAt(uS, amzp_innerBlur, amzTexture(0, uS)).a;
                float is = amzp_innerStr * a * (1.0 - sa);
                res = ov(float4(amzp_shCol.rgb * is, is), res);
            }
            if (amzp_innerGlow > 0.001) {
                float ig = clamp(amzp_innerGlow * e * e, 0.0, 1.0) * a;
                res = ov(float4(amzp_hiCol.rgb * ig, ig), res);
            }
            if ((amzp_bevelOn>0.5)) {
                float gm = amzSource_gl * R / 0.89;
                float2 nxy;
                if (int(amzp_bevelStyle) == 1) {
                    nxy = -gd * 0.9 * amzp_bevelDepth * smoothstep(0.03, 0.4, gm);
                } else {
                    float f = 1.0;
                    if (int(amzp_bevelStyle) == 2) f = cos(clamp((h - 0.5) * 2.0, 0.0, 1.0) * 3.14159);
                    nxy = -g * amzp_bevelDepth * R * f;
                }
                float3 N = normalize(float3(nxy, 1.0));
                float E = mix(0.17, 1.4, amzp_lightHeight);
                float sE = sin(E), cE = cos(E);
                float3 Lf = float3(L2 * cE, sE);
                float3 Lb = float3(-L2 * cE, sE);
                float dl = dot(N, Lf) - sE;
                float sh = clamp(max(-dl, 0.0) * 1.5 * amzp_shStr, 0.0, 1.0) * a;
                res = ov(float4(amzp_shCol.rgb * sh, sh), res);
                float bk = clamp(max(dot(N, Lb) - sE, 0.0) * 1.5 * amzp_backStr, 0.0, 1.0) * a;
                res = ov(float4(amzp_hiCol.rgb * bk, bk), res);
                float hi = clamp(max(dl, 0.0) * 1.5 * amzp_hiStr, 0.0, 1.0) * a;
                res = ov(float4(amzp_hiCol.rgb * hi, hi), res);
                float3 Hh = normalize(Lf + float3(0.0, 0.0, 1.0));
                float sp = max(pow(max(dot(N, Hh), 0.0), amzp_shin) - pow(Hh.z, amzp_shin), 0.0);
                sp = clamp(sp * amzp_specStr, 0.0, 1.0) * a;
                res = ov(float4(amzp_hiCol.rgb * sp, sp), res);
            }
            if ((amzp_borderOn>0.5)) {
                float dEdge = sg * log(clamp(h, 0.002, 0.998) / (1.0 - clamp(h, 0.002, 0.998))) / 1.702;
                float bm = 1.0 - smoothstep(amzp_borderW - 0.5, amzp_borderW + 0.5, dEdge);
                float lit = smoothstep(-0.3, 1.0, dot(-gd, L2)) * 0.85 + 0.15;
                float bl = bm * amzp_borderCol.a * mix(1.0, lit, amzp_borderLit) * a;
                res = ov(float4(amzp_borderCol.rgb * bl, bl), res);
            }
        }
        if ((amzp_dropOn>0.5)) {
            float2 dof = float2(cos(radians(amzp_dropAngle)), sin(radians(amzp_dropAngle))) * amzp_dropDist;
            float2 uD = l2s(amzLayerNorm() - dof / W);
            float da = blurAt(uD, amzp_dropBlur, amzTexture(0, uD)).a;
            float ds = amzp_dropCol.a * da * ((amzp_dropKnock>0.5) ? (1.0 - clamp(a, 0.0, 1.0)) : 1.0);
            res = ov(res, float4(amzp_dropCol.rgb * ds, ds));
        }
        res = mix(src, res, amzp_alpha);
        res.rgb += (hh(uvS * screen.zw + 7.0) - 0.5) / 255.0 * step(0.003, res.a);
        amzOutput = float4(clamp(res.rgb, 0.0, res.a), clamp(res.a, 0.0, 1.0));
        if (!(amzp_overdrawOn>0.5)) amzOutput *= src.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

stages.sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
